import { useState } from 'react';
import { JxInputField, JxSelect, JxSwitch, JxButton, JxToast } from '@jinx-ui/react';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const ROLE_OPTIONS = [
  { value: 'member', label: 'Участник' },
  { value: 'admin', label: 'Администратор' },
  { value: 'viewer', label: 'Наблюдатель' },
];

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('member');
  const [notify, setNotify] = useState(true);
  const [submitted, setSubmitted] = useState(false);

  const emailTouched = email.length > 0;
  const emailValid = EMAIL_PATTERN.test(email);
  const emailError = emailTouched && !emailValid ? 'Введите корректный адрес почты' : undefined;
  const canSubmit = emailValid;

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!canSubmit) return;
    setSubmitted(true);
  };

  return (
    <div style={{ maxWidth: 420, display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-md, 16px)' }}>
      {submitted && (
        <JxToast
          variant="success"
          title="Приглашение отправлено"
          message={`Приглашение на ${email} успешно отправлено`}
          onClose={() => setSubmitted(false)}
        />
      )}

      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-md, 16px)' }}>
        <JxInputField
          label="Электронная почта"
          type="email"
          required
          placeholder="name@company.com"
          helperText="На этот адрес придёт приглашение в команду"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          errorText={emailError}
        />

        <JxSelect
          label="Роль"
          options={ROLE_OPTIONS}
          value={role}
          onValueChange={setRole}
        />

        <JxSwitch
          label="Отправить уведомление"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <JxButton type="submit" variant="primary" disabled={!canSubmit}>
          Пригласить
        </JxButton>
      </form>
    </div>
  );
}

